```ts
interface Command {
  execute(): void;
  undo(): void;
}

class BoldCommand implements Command {
  constructor(private doc: Document, private range: Range) {}
  execute() { this.doc.applyBold(this.range); }
  undo() { this.doc.removeBold(this.range); }
}

class CommandHistory {
  private stack: Command[] = [];
  run(cmd: Command) {
    cmd.execute();
    this.stack.push(cmd);
  }
  undoLast() {
    const cmd = this.stack.pop();
    if (cmd) cmd.undo();
  }
}

const history = new CommandHistory();
history.run(new BoldCommand(doc, selection));
history.undoLast();   // reverses exactly that command, nothing else
```

`CommandHistory` never knows what "bold" is — it just calls `execute()`/`undo()` on whatever `Command` it's handed, which is exactly what makes one undo stack work for every action type in the editor.
